botLibAdd("bulwark", "// BULWARK: the turtle. Holds the spur in front of its own bird: warriors\n// stand at its head, hunters a step behind, and one seat spends the side's\n// first gold on turrets along it. Everyone else chops the woods by the roost\n// for gear. It only leaves when it has just wiped an attack, or the snow has\n// been quiet a long while, and the side is up: then the first seat calls a sally, everyone goes at the\n// rival bird together, and the first blow on its own bird calls them home.\n// Shows `cmd` builds, team `say` and reading your own bird's `hitT`.\ndefineBot({\n  name: 'BULWARK',\n  author: 'Softfall',\n  version: '1.0',\n\n  init(hello) {\n    this.drawT = 0; this.swing = false;\n    this.quietT = 0;      // s since anyone of the side last saw a rival near home\n    this.sally = 0;       // the match second the side's sally began (0: none)\n    this.tried = {};      // turret sites already tried\n    this.lead = hello.seat === hello.team; // the side's first seat calls the sally and builds\n    this.seenT = -99; this.seenN = 0;      // when, and how many, rivals were last at the spur\n  },\n\n  think(obs) {\n    const me = obs.me;\n    if (me.dead || me.aboard || me.falling) return { think: { goal: 'IDLE', why: me.dead ? 'DOWN' : 'RIDING' } };\n    const act = {};\n    const dist = (o) => Math.hypot(o.x - me.x, o.y - me.y);\n    if (me.skillPts > 0) { const k = pickKey(me, me.cls === 'WARRIOR' ? [0, 2, 3, 1] : [1, 0, 2, 3]); if (k >= 0) act.cmd = { kind: 'ability', i: k }; }\n\n    for (const m of obs.team) if (m.say) {\n      if (m.say.sally) this.sally = this.sally || obs.time;\n      if (m.say.home) this.sally = 0;\n    }\n    const own = obs.eagles.find((e) => e.team === me.team && e.state === 'down');\n    const bird = obs.eagles.find((e) => e.team !== me.team && e.state === 'down');\n    if (!own) { act.goTo = { x: me.x, y: me.y }; act.think = { goal: 'IDLE', why: 'NO ROOST YET' }; return act; }\n\n    // the post: two thirds of the way from the bird to the head of its spur\n    const mouth = own.mouth || own;\n    const post = { x: own.x + (mouth.x - own.x) * 0.66, y: own.y + (mouth.y - own.y) * 0.66 };\n    const foes = obs.enemies.concat(obs.soldiers.filter((s) => s.team !== me.team));\n    const near = foes.filter((f) => Math.hypot(f.x - post.x, f.y - post.y) < 340);\n    const struck = own.hitT < 3;\n    // quiet: no rival player near the spur (waves of soldiers come and go regardless)\n    this.quietT = struck || obs.enemies.some((f) => Math.hypot(f.x - post.x, f.y - post.y) < 500) ? 0 : this.quietT + 0.1;\n\n    // a sally: out together, home at the first blow on our bird\n    if (this.sally && (struck || obs.time - this.sally > 90)) {\n      this.sally = 0;\n      if (struck) act.say = { home: true };\n    }\n    // a wipe: three or more were at the spur, and now for 6 s nobody is\n    const atSpur = obs.enemies.filter((f) => Math.hypot(f.x - post.x, f.y - post.y) < 500).length;\n    if (atSpur) { this.seenN = Math.max(atSpur, obs.time - this.seenT < 10 ? this.seenN : 0); this.seenT = obs.time; }\n    const wiped = !atSpur && this.seenN >= 3 && obs.time - this.seenT > 6 && obs.time - this.seenT < 20;\n    if (this.lead && !this.sally && bird && !struck && (wiped || (this.quietT > 45 && obs.time > 240))) {\n      const up = obs.allies.filter((a) => !a.dead && !a.aboard).length + 1;\n      if (up >= (wiped ? 4 : 5)) { this.sally = obs.time; this.seenN = 0; act.say = { sally: true }; }\n    }\n\n    // anything in front of the post, or at the bird: everyone answers\n    let foe = null;\n    for (const f of this.sally ? foes : near) if (!foe || dist(f) < dist(foe)) foe = f;\n    if (foe && (!this.sally || dist(foe) < 200)) {\n      fight(this, me, foe, act);\n      // a hunter fights from the post, never past it\n      if (me.cls === 'HUNTER' && !this.sally && Math.hypot(me.x - post.x, me.y - post.y) > 140) act.goTo = { x: post.x, y: post.y };\n      act.think = { goal: 'DEFEND', why: struck ? 'BIRD HIT' : 'AT THE SPUR', plan: this.sally ? 'SALLY' : 'HOLD', mood: 'STEADY', target: { kind: foe.cls ? 'player' : 'soldier', id: foe.id, x: foe.x, y: foe.y } };\n      return act;\n    }\n    if (struck) {\n      // hit by something nobody can see (a buried hunter): sweep round the bird\n      const a = obs.time * 1.3 + me.id;\n      act.goTo = { x: own.x + Math.cos(a) * 70, y: own.y + Math.sin(a) * 70 };\n      act.aim = [own.x + Math.cos(a) * 120, own.y + Math.sin(a) * 120];\n      act.think = { goal: 'DEFEND', why: 'BIRD HIT', plan: 'HOLD', mood: 'ALARMED' };\n      return act;\n    }\n\n    if (this.sally && bird) {\n      siege(this, me, bird, act);\n      act.think = { goal: 'PUSH', why: 'SALLY', plan: 'SALLY', mood: 'BOLD', target: { kind: 'bird', id: bird.team, x: bird.x, y: bird.y } };\n      return act;\n    }\n\n    if (me.hp < me.maxHp * 0.6 && me.food.berry > 0) { act.eatBerry = true; act.think = { goal: 'EAT', why: 'LOW HP' }; return act; }\n\n    // the first seat builds turrets along the spur while it has the gold\n    if (this.lead && !act.cmd && me.gold >= 10) {\n      const mine = obs.structs.filter((s) => s.type === 'turret' && s.team === me.team).length;\n      const site = mine < 6 && turretSite(this, own, mouth, mine);\n      if (site) {\n        const x = site.tx * 16 + 8, y = site.ty * 16 + 8, d = dist({ x, y });\n        act.goTo = { x, y, reach: 1 };\n        if (d < 56) { act.cmd = { kind: 'build', tx: site.tx, ty: site.ty, id: 'turret', rot: 0 }; this.tried[site.tx + ',' + site.ty] = true; }\n        act.think = { goal: 'BUILD', why: 'TURRET ' + (mine + 1) + ' OF 6', plan: 'HOLD', target: { kind: 'point', x, y } };\n        return act;\n      }\n    }\n    // rich: raise a turret a tier (a top-tier one just refuses)\n    if (this.lead && !act.cmd && me.gold >= 80) {\n      const t = obs.structs.filter((s) => s.type === 'turret' && s.team === me.team && !s.building)[(obs.tick / 60 | 0) % 6];\n      if (t && Math.hypot(t.tx * 16 + 8 - me.x, t.ty * 16 + 8 - me.y) < 56) act.cmd = { kind: 'upgrade', tx: t.tx, ty: t.ty };\n      else if (t) { act.goTo = { x: t.tx * 16 + 8, y: t.ty * 16 + 8, reach: 1 }; act.think = { goal: 'BUILD', why: 'UPGRADE', plan: 'HOLD' }; return act; }\n    }\n    buyGear(this, me, act, this.lead ? 40 : 0);\n\n    // the rest of the time: warriors at the post, hunters chop close by\n    if (me.cls === 'WARRIOR' && obs.allies.some((a) => a.cls === 'HUNTER' && !a.dead)) {\n      act.goTo = { x: post.x, y: post.y };\n      act.aim = [mouth.x, mouth.y];\n      act.think = { goal: 'GUARD', why: 'HOLD THE SPUR', plan: 'HOLD', mood: 'STEADY', target: { kind: 'point', x: post.x, y: post.y } };\n      return act;\n    }\n    const n = pickNode(this, obs, own, 220, ['tree', 'bush', 'rock']);\n    if (n) { work(me, n, act); act.think = { goal: 'GATHER', why: 'GOLD FOR GEAR', plan: 'HOLD', target: { kind: 'point', x: n.x, y: n.y } }; return act; }\n    act.goTo = { x: post.x, y: post.y };\n    act.think = { goal: 'GUARD', why: 'NOTHING TO DO', plan: 'HOLD' };\n    return act;\n  },\n});\n\n// the next untried turret site: pairs either side of the spur, from the head\n// back toward the bird (a site that never rose is not tried again)\nfunction turretSite(bot, own, mouth, mine) {\n  const L = Math.max(1, Math.hypot(mouth.x - own.x, mouth.y - own.y));\n  const ux = (mouth.x - own.x) / L, uy = (mouth.y - own.y) / L;\n  for (const t of [0.75, 0.55, 0.9, 0.4]) for (const side of [-1, 1]) for (const off of [40, 56]) {\n    const x = own.x + (mouth.x - own.x) * t - uy * off * side, y = own.y + (mouth.y - own.y) * t + ux * off * side;\n    const tx = Math.floor(x / 16), ty = Math.floor(y / 16);\n    if (!bot.tried[tx + ',' + ty]) return { tx, ty };\n  }\n  return null;\n}\n\n// ---- shared moves (every bot file stands alone, so these are copied) --------\n\n// the first key in `order` with a level still to buy\nfunction pickKey(me, order) {\n  for (const k of order) if (me.abilities[k] && me.abilities[k].lv < 3) return k;\n  return -1;\n}\n\n// strike the rival bird: a hunter stands off past the wing gust (it reaches\n// 76 px) and taps shots; a warrior walks in and swings E\nfunction siege(bot, me, bird, act) {\n  const d = Math.hypot(bird.x - me.x, bird.y - me.y);\n  act.aim = [bird.x, bird.y];\n  if (me.cls === 'HUNTER') {\n    if (d > 115) act.goTo = { x: bird.x, y: bird.y, reach: 1 };\n    else if (d < 84) act.move = [(me.x - bird.x) / d, (me.y - bird.y) / d];\n    if (d < 135) { bot.drawT++; act.fire = bot.drawT % 2 === 1; } // further out, the woods eat the shots\n  } else {\n    act.goTo = { x: bird.x, y: bird.y, reach: 1 };\n    act.work = d < 56;\n  }\n}\n\n// one exchange with a rival body, by class, with the four keys\nfunction fight(bot, me, foe, act) {\n  const d = Math.max(1, Math.hypot(foe.x - me.x, foe.y - me.y));\n  const lead = me.cls === 'HUNTER' ? d / 320 : 0.1;\n  act.aim = [foe.x + (foe.vx || 0) * lead, foe.y + (foe.vy || 0) * lead];\n  const ab = me.abilities;\n  if (me.cls === 'WARRIOR') {\n    act.goTo = { x: foe.x, y: foe.y };\n    if (ab[1].ready && d > 48 && d < 110) act.ability = 1;                         // rush in\n    else if (ab[2].ready && d < 34) act.ability = 2;                               // stomp\n    else if (ab[3].ready && d < 30 && foe.hp < foe.maxHp * 0.45) act.ability = 3;  // execute\n    bot.swing = !bot.swing;\n    act.fire = d < 40 && bot.swing;\n  } else {\n    if (d < 100) act.move = [(me.x - foe.x) / d, (me.y - foe.y) / d];\n    else if (d > 220) act.goTo = { x: foe.x, y: foe.y };\n    if (ab[1].ready && d < 110) act.ability = 1;                                   // net, and the kick back\n    else if (ab[0].ready && d > 150 && d < 400) act.ability = 0;                   // piercing shot\n    bot.drawT++;\n    act.fire = bot.drawT < 8;\n    if (!act.fire) bot.drawT = 0;\n  }\n  if (me.hp < me.maxHp * 0.3 && d < 60) act.dodge = true;\n}\n\n// a resource node to work near `home`: the nearest of `kinds` within `range`,\n// skipping any the pathfinder found no way to (me.nav says 'fail' the think\n// after a goTo with no route)\nfunction pickNode(bot, obs, home, range, kinds) {\n  const me = obs.me;\n  bot.bad = bot.bad || {};\n  if (me.nav === 'fail' && bot.node) bot.bad[bot.node.key] = true;\n  let best = null, bd = Infinity;\n  for (const n of obs.nodes) {\n    const key = n.tx + ',' + n.ty;\n    if (!kinds.includes(n.kind) || bot.bad[key]) continue;\n    const x = n.tx * 16 + 8, y = n.ty * 16 + 8;\n    if (Math.hypot(x - home.x, y - home.y) > range) continue;\n    const d = Math.hypot(x - me.x, y - me.y) * (n.kind === 'tree' ? 1.5 : 1); // anything but a pine is worth a detour\n    if (d < bd) { bd = d; best = { x, y, kind: n.kind, key }; }\n  }\n  bot.node = best;\n  return best;\n}\n\n// work a node: walk up beside it and hold E (a rock needs no key: standing by it mines it)\nfunction work(me, n, act) {\n  const d = Math.hypot(n.x - me.x, n.y - me.y);\n  act.goTo = { x: n.x, y: n.y, reach: 1 };\n  act.aim = [n.x, n.y];\n  act.work = d < 28 && n.kind !== 'rock';\n}\n\n// gold to spare: the next gear piece, round the four in turn (the obs does\n// not say which pieces are already bought, so a full one is just skipped)\nfunction buyGear(bot, me, act, keep) {\n  if (act.cmd || me.gold < keep + 10) return;\n  bot.gear = ((bot.gear || 0) + 1) % 4;\n  act.cmd = { kind: 'gear', piece: bot.gear };\n}\n");
botLibAdd("keeper", "// KEEPER: stays home. Chops the woods by its own bird for gold, spends it on\n// gear, and turns on anything that comes for the bird. Shows work (E), an\n// order (`cmd`) and reading your own bird's `hitT`.\ndefineBot({\n  name: 'KEEPER',\n  author: 'Softfall',\n  version: '1.0',\n\n  init(hello) { this.drawT = 0; this.gear = 0; this.bad = new Set(); this.tree = null; },\n\n  think(obs) {\n    const me = obs.me;\n    if (me.dead || me.aboard) return { think: { goal: 'IDLE', why: 'DOWN' } };\n    const act = {};\n    if (me.skillPts > 0) act.ability = me.abilities.reduce((b, a) => (a.lv < b.lv ? a : b)).key;\n    else if (me.gold > 120) { act.cmd = { kind: 'gear', piece: this.gear }; this.gear = (this.gear + 1) % 4; }\n\n    const own = obs.eagles.find((e) => e.team === me.team && e.state === 'down');\n    const home = own || { x: me.x, y: me.y };\n    const dist = (o) => Math.hypot(o.x - me.x, o.y - me.y);\n    // anyone within 300 of home is the enemy of the day\n    let foe = null;\n    for (const e of obs.enemies.concat(obs.soldiers.filter((s) => s.team !== me.team))) {\n      if (Math.hypot(e.x - home.x, e.y - home.y) < 300 && (!foe || dist(e) < dist(foe))) foe = e;\n    }\n    if (foe) {\n      const d = dist(foe);\n      act.aim = [foe.x, foe.y];\n      act.think = { goal: 'DEFEND', why: own && own.hitT < 8 ? 'BIRD HIT' : 'AT THE ROOST', target: { kind: foe.cls ? 'player' : 'soldier', id: foe.id, x: foe.x, y: foe.y } };\n      if (me.cls === 'WARRIOR') { act.goTo = { x: foe.x, y: foe.y }; act.fire = d < 40 && (obs.tick / 6) % 2 < 1; }\n      else { this.drawT++; act.fire = this.drawT < 8; if (!act.fire) this.drawT = 0; }\n      return act;\n    }\n    this.drawT = 0;\n\n    // hurt: eat\n    if (me.hp < me.maxHp * 0.6 && me.food.berry > 0) { act.eatBerry = true; act.think = { goal: 'EAT', why: 'LOW HP' }; return act; }\n\n    // work the nearest tree within 250 of home; a tree it found no way to is\n    // skipped from then on (me.nav says 'fail' when the last goTo had no route)\n    if (me.nav === 'fail' && this.tree) this.bad.add(this.tree.key);\n    let tree = null, td = Infinity;\n    for (const n of obs.nodes) {\n      if (n.kind !== 'tree' || this.bad.has(n.tx + ',' + n.ty)) continue;\n      const x = n.tx * 16 + 8, y = n.ty * 16 + 8;\n      if (Math.hypot(x - home.x, y - home.y) > 250) continue;\n      const d = Math.hypot(x - me.x, y - me.y);\n      if (d < td) { td = d; tree = { x, y, key: n.tx + ',' + n.ty }; }\n    }\n    this.tree = tree;\n    if (tree) {\n      act.goTo = { x: tree.x, y: tree.y, reach: 1 };\n      act.aim = [tree.x, tree.y];\n      act.work = td < 28;\n      act.think = { goal: 'GATHER', why: 'WOOD FOR GOLD', target: { kind: 'point', x: tree.x, y: tree.y } };\n      return act;\n    }\n    act.goTo = { x: home.x + 40, y: home.y + 40 };\n    act.think = { goal: 'GUARD', why: 'NOTHING TO DO' };\n    return act;\n  },\n});\n");
botLibAdd("pack", "// PACK: waits for friends, then goes for the rival bird together, and fights\n// as one. Shows the team channel: `say` reaches your teammates' next obs.team.\ndefineBot({\n  name: 'PACK',\n  author: 'Softfall',\n  version: '1.0',\n\n  init(hello) {\n    this.team = hello.team;\n    this.drawT = 0;\n    this.focus = null;  // the rival the side agreed to shoot\n    this.go = false;    // the pack has gathered and is moving\n  },\n\n  think(obs) {\n    const me = obs.me;\n    if (me.dead || me.aboard) { this.go = false; return { think: { goal: 'IDLE', why: 'DOWN' } }; }\n    const act = {};\n    if (me.skillPts > 0) act.ability = me.abilities.reduce((b, a) => (a.lv < b.lv ? a : b)).key;\n\n    // what the side said: a focus target, or \"go\"\n    for (const m of obs.team) {\n      if (m.say && m.say.focus !== undefined) this.focus = m.say.focus;\n      if (m.say && m.say.go) this.go = true;\n    }\n\n    // fight: the agreed target if it is in sight, else the nearest\n    const dist = (o) => Math.hypot(o.x - me.x, o.y - me.y);\n    let foe = obs.enemies.find((e) => e.id === this.focus) || null;\n    if (!foe || dist(foe) > 260) {\n      foe = null;\n      for (const e of obs.enemies) if (dist(e) < 260 && (!foe || dist(e) < dist(foe))) foe = e;\n      if (foe) act.say = { focus: foe.id }; // call it for the side\n    }\n    const melee = me.cls === 'WARRIOR';\n    if (foe) {\n      const d = dist(foe);\n      act.aim = [foe.x + foe.vx * 0.2, foe.y + foe.vy * 0.2];\n      act.think = { goal: 'FIGHT', why: foe.id === this.focus ? 'FOCUS' : 'NEAREST', plan: 'PACK', target: { kind: 'player', id: foe.id, x: foe.x, y: foe.y } };\n      if (melee) { act.goTo = { x: foe.x, y: foe.y }; act.fire = d < 40 && (obs.tick / 6) % 2 < 1; }\n      else {\n        if (d < 100) act.move = [(me.x - foe.x) / d, (me.y - foe.y) / d];\n        this.drawT++;\n        act.fire = this.drawT < 8;\n        if (!act.fire) this.drawT = 0;\n      }\n      if (me.hp < me.maxHp * 0.3) act.dodge = true;\n      return act;\n    }\n\n    const own = obs.eagles.find((e) => e.team === me.team && e.state === 'down');\n    const bird = obs.eagles.find((e) => e.team !== me.team && e.state === 'down');\n    if (!own || !bird) {\n      act.goTo = { x: me.x < 1856 ? me.x + 64 : me.x - 64, y: me.y };\n      act.think = { goal: 'ROAM', why: 'NO BIRDS YET' };\n      return act;\n    }\n\n    // gather at your own bird's road junction until three of the side stand there\n    const rally = own.mouth || own;\n    if (!this.go) {\n      const here = obs.allies.filter((a) => !a.dead && Math.hypot(a.x - rally.x, a.y - rally.y) < 160).length\n        + (Math.hypot(me.x - rally.x, me.y - rally.y) < 160 ? 1 : 0);\n      if (here >= 3) { this.go = true; act.say = { go: true }; }\n      else {\n        act.goTo = { x: rally.x, y: rally.y };\n        act.think = { goal: 'RALLY', why: here + ' OF 3 HERE', plan: 'PACK', target: { kind: 'point', x: rally.x, y: rally.y } };\n        return act;\n      }\n    }\n\n    // the push: to the rival bird, strike it (warrior) or shoot it (hunter)\n    const d = Math.hypot(bird.x - me.x, bird.y - me.y);\n    act.aim = [bird.x, bird.y];\n    act.think = { goal: 'PUSH', why: 'PACK IS GO', plan: 'PACK', target: { kind: 'bird', id: bird.team, x: bird.x, y: bird.y } };\n    if (melee || d > 100) act.goTo = { x: bird.x, y: bird.y, reach: 1 };\n    if (melee) act.work = d < 40;\n    else if (d < 140) { this.drawT++; act.fire = this.drawT % 8 !== 0; }\n    if (me.hp < me.maxHp * 0.25) this.go = false; // too hurt: back to the rally\n    return act;\n  },\n});\n");
botLibAdd("prospector", "// PROSPECTOR: the farmer. Spends the early match getting rich: loot on the\n// ground first, then chests, rocks, berry bushes, rabbits and deer, and pines\n// when nothing better is near. Every coin goes on armour and every point on\n// the class keys. It only defends when its own bird is struck. At nine\n// minutes (or from five, once a seat's armour is full) it calls the push, and the\n// whole side goes for the rival bird at once, geared. Beats sides that\n// trade early and even; loses to an early raid.\nconst PUSH_AT = 540;   // s: the push, called by the clock if nobody called it sooner\nconst PUSH_FULL = 300; // s: the earliest a seat in full armour may call it\ndefineBot({\n  name: 'PROSPECTOR',\n  author: 'Softfall',\n  version: '1.0',\n\n  init(hello) { this.drawT = 0; this.swing = false; this.push = false; this.spent = 0; this.lastGold = 0; },\n\n  think(obs) {\n    const me = obs.me;\n    if (me.dead || me.aboard || me.falling) return { think: { goal: 'IDLE', why: me.dead ? 'DOWN' : 'RIDING' } };\n    const act = {};\n    const dist = (o) => Math.hypot(o.x - me.x, o.y - me.y);\n    if (me.skillPts > 0) { const k = pickKey(me, me.cls === 'WARRIOR' ? [1, 3, 2, 0] : [0, 1, 3, 2]); if (k >= 0) act.cmd = { kind: 'ability', i: k }; }\n\n    for (const m of obs.team) if (m.say && m.say.push) this.push = true;\n    if (!this.push && obs.time > PUSH_AT) { this.push = true; act.say = { push: true }; }\n    // armour: count what a buy took off the purse; 260 gold buys all four pieces to the top\n    if (this.wantGear && [10, 20, 35].includes(this.lastGold - me.gold)) this.spent += this.lastGold - me.gold;\n    this.wantGear = false;\n    this.lastGold = me.gold;\n    if (!this.push && this.spent >= 240 && obs.time > PUSH_FULL) { this.push = true; act.say = { push: true }; }\n\n    const own = obs.eagles.find((e) => e.team === me.team && e.state === 'down');\n    const bird = obs.eagles.find((e) => e.team !== me.team && e.state === 'down');\n    const home = own || { x: me.x, y: me.y };\n    const foes = obs.enemies.concat(obs.soldiers.filter((s) => s.team !== me.team));\n\n    // a fight it can't walk away from, or anything at its own bird when struck\n    let foe = null;\n    // farming, it only turns on a soldier that is on top of it\n    for (const f of foes) if (dist(f) < (this.push ? 220 : f.cls ? 130 : 50) && (!foe || dist(f) < dist(foe))) foe = f;\n    if (!foe && own && own.hitT < 4 && dist(own) < 900) {\n      for (const f of foes) if (Math.hypot(f.x - own.x, f.y - own.y) < 300 && (!foe || dist(f) < dist(foe))) foe = f;\n      if (!foe) {\n        act.goTo = { x: own.x, y: own.y, reach: 1 };\n        act.think = { goal: 'DEFEND', why: 'BIRD HIT', plan: this.push ? 'PUSH' : 'FARM' };\n        return act;\n      }\n    }\n    if (foe) {\n      fight(this, me, foe, act);\n      act.think = { goal: own && Math.hypot(foe.x - own.x, foe.y - own.y) < 300 ? 'DEFEND' : 'FIGHT', why: 'TOO CLOSE', plan: this.push ? 'PUSH' : 'FARM', target: { kind: foe.cls ? 'player' : 'soldier', id: foe.id, x: foe.x, y: foe.y } };\n      return act;\n    }\n\n    if (me.hp < me.maxHp * 0.6 && me.food.berry > 0) { act.eatBerry = true; act.think = { goal: 'EAT', why: 'LOW HP' }; return act; }\n    if (me.hp < me.maxHp * 0.6 && me.food.fish > 0) { act.eatFish = true; act.think = { goal: 'EAT', why: 'LOW HP' }; return act; }\n    if (!act.cmd && me.gold >= 45) { buyGear(this, me, act, 35); this.wantGear = !!act.cmd; }\n\n    if (this.push && bird) {\n      siege(this, me, bird, act);\n      act.think = { goal: 'PUSH', why: obs.time > PUSH_AT ? 'TIME TO CASH IN' : 'ARMOUR FULL', plan: 'PUSH', mood: 'BOLD', target: { kind: 'bird', id: bird.team, x: bird.x, y: bird.y } };\n      return act;\n    }\n\n    // loot on the ground near, then the best node\n    const drop = obs.drops.filter((d) => dist(d) < 200).sort((a, b) => dist(a) - dist(b))[0];\n    if (drop) {\n      act.goTo = { x: drop.x, y: drop.y };\n      act.think = { goal: 'LOOT', why: drop.type, plan: 'FARM', target: { kind: 'drop', id: drop.id, x: drop.x, y: drop.y } };\n      return act;\n    }\n    const game = obs.animals.filter((a) => (a.kind === 'rabbit' || a.kind === 'deer') && dist(a) < 220).sort((a, b) => dist(a) - dist(b))[0];\n    if (game) {\n      fight(this, me, game, act);\n      act.think = { goal: 'HUNT', why: game.kind.toUpperCase(), plan: 'FARM', target: { kind: 'animal', id: game.id, x: game.x, y: game.y } };\n      return act;\n    }\n    // the side spreads out: each seat farms its own patch on its half\n    const half = { x: home.x + (1856 - home.x) * ((me.id >> 1) % 5) / 6, y: home.y + (1856 - home.y) * ((me.id >> 1) % 5) / 6 };\n    const n = pickNode(this, obs, half, 700, ['chest', 'rock', 'bush', 'tree']);\n    if (n) {\n      work(me, n, act);\n      act.think = { goal: n.kind === 'rock' ? 'MINE' : 'GATHER', why: n.kind.toUpperCase(), plan: 'FARM', target: { kind: 'object', x: n.x, y: n.y } };\n      return act;\n    }\n    act.goTo = { x: half.x, y: half.y };\n    act.think = { goal: 'ROAM', why: 'LOOKING FOR GOLD', plan: 'FARM' };\n    return act;\n  },\n});\n\n// ---- shared moves (every bot file stands alone, so these are copied) --------\n\n// the first key in `order` with a level still to buy\nfunction pickKey(me, order) {\n  for (const k of order) if (me.abilities[k] && me.abilities[k].lv < 3) return k;\n  return -1;\n}\n\n// strike the rival bird: a hunter stands off past the wing gust (it reaches\n// 76 px) and taps shots; a warrior walks in and swings E\nfunction siege(bot, me, bird, act) {\n  const d = Math.hypot(bird.x - me.x, bird.y - me.y);\n  act.aim = [bird.x, bird.y];\n  if (me.cls === 'HUNTER') {\n    if (d > 115) act.goTo = { x: bird.x, y: bird.y, reach: 1 };\n    else if (d < 84) act.move = [(me.x - bird.x) / d, (me.y - bird.y) / d];\n    if (d < 135) { bot.drawT++; act.fire = bot.drawT % 2 === 1; } // further out, the woods eat the shots\n  } else {\n    act.goTo = { x: bird.x, y: bird.y, reach: 1 };\n    act.work = d < 56;\n  }\n}\n\n// one exchange with a rival body, by class, with the four keys\nfunction fight(bot, me, foe, act) {\n  const d = Math.max(1, Math.hypot(foe.x - me.x, foe.y - me.y));\n  const lead = me.cls === 'HUNTER' ? d / 320 : 0.1;\n  act.aim = [foe.x + (foe.vx || 0) * lead, foe.y + (foe.vy || 0) * lead];\n  const ab = me.abilities;\n  if (me.cls === 'WARRIOR') {\n    act.goTo = { x: foe.x, y: foe.y };\n    if (ab[1].ready && d > 48 && d < 110) act.ability = 1;                         // rush in\n    else if (ab[2].ready && d < 34) act.ability = 2;                               // stomp\n    else if (ab[3].ready && d < 30 && foe.hp < foe.maxHp * 0.45) act.ability = 3;  // execute\n    bot.swing = !bot.swing;\n    act.fire = d < 40 && bot.swing;\n  } else {\n    if (d < 100) act.move = [(me.x - foe.x) / d, (me.y - foe.y) / d];\n    else if (d > 220) act.goTo = { x: foe.x, y: foe.y };\n    if (ab[1].ready && d < 110) act.ability = 1;                                   // net, and the kick back\n    else if (ab[0].ready && d > 150 && d < 400) act.ability = 0;                   // piercing shot\n    bot.drawT++;\n    act.fire = bot.drawT < 8;\n    if (!act.fire) bot.drawT = 0;\n  }\n  if (me.hp < me.maxHp * 0.3 && d < 60) act.dodge = true;\n}\n\n// a resource node to work near `home`: the nearest of `kinds` within `range`,\n// skipping any the pathfinder found no way to (me.nav says 'fail' the think\n// after a goTo with no route)\nfunction pickNode(bot, obs, home, range, kinds) {\n  const me = obs.me;\n  bot.bad = bot.bad || {};\n  if (me.nav === 'fail' && bot.node) bot.bad[bot.node.key] = true;\n  let best = null, bd = Infinity;\n  for (const n of obs.nodes) {\n    const key = n.tx + ',' + n.ty;\n    if (!kinds.includes(n.kind) || bot.bad[key]) continue;\n    const x = n.tx * 16 + 8, y = n.ty * 16 + 8;\n    if (Math.hypot(x - home.x, y - home.y) > range) continue;\n    const d = Math.hypot(x - me.x, y - me.y) * (n.kind === 'tree' ? 1.5 : 1); // anything but a pine is worth a detour\n    if (d < bd) { bd = d; best = { x, y, kind: n.kind, key }; }\n  }\n  bot.node = best;\n  return best;\n}\n\n// work a node: walk up beside it and hold E (a rock needs no key: standing by it mines it)\nfunction work(me, n, act) {\n  const d = Math.hypot(n.x - me.x, n.y - me.y);\n  act.goTo = { x: n.x, y: n.y, reach: 1 };\n  act.aim = [n.x, n.y];\n  act.work = d < 28 && n.kind !== 'rock';\n}\n\n// gold to spare: the next gear piece, round the four in turn (the obs does\n// not say which pieces are already bought, so a full one is just skipped)\nfunction buyGear(bot, me, act, keep) {\n  if (act.cmd || me.gold < keep + 10) return;\n  bot.gear = ((bot.gear || 0) + 1) % 4;\n  act.cmd = { kind: 'gear', piece: bot.gear };\n}\n");
botLibAdd("raider", "// RAIDER: the rusher. The moment the rival bird lands, every seat runs the\n// road at it and never stops. Hunters stand off outside the wing gust and\n// loose quick shots (a bird takes the same chip from any arrow, drawn or\n// not); warriors swing E at it and take the buffets. It only turns to fight\n// what gets in its face, and it does not wait for anyone after a respawn:\n// the pressure is the plan (it waits for one partner at most). Beats sides that farm; loses to a side that\n// holds its roost.\ndefineBot({\n  name: 'RAIDER',\n  author: 'Softfall',\n  version: '1.0',\n\n  init(hello) { this.drawT = 0; this.swing = false; this.n = 0; this.waitT = 0; },\n\n  think(obs) {\n    const me = obs.me;\n    this.n++;\n    if (me.dead || me.aboard || me.falling) { this.waitT = me.dead ? 8 : 0; return { think: { goal: 'IDLE', why: me.dead ? 'DOWN' : 'RIDING' } }; }\n    const act = {};\n    const dist = (o) => Math.hypot(o.x - me.x, o.y - me.y);\n\n    // points: the rush and the net first (they open a path), then the rest\n    if (me.skillPts > 0) { const k = pickKey(me, me.cls === 'WARRIOR' ? [1, 2, 3, 0] : [1, 0, 3, 2]); if (k >= 0) act.cmd = { kind: 'ability', i: k }; }\n\n    const bird = obs.eagles.find((e) => e.team !== me.team && e.state === 'down');\n    const foes = obs.enemies.concat(obs.soldiers.filter((s) => s.team !== me.team));\n    // only what is close enough to stop the raid gets an answer\n    // soldiers pour out of the barracks behind the bird all match long: a hunter\n    // shoots past them, a warrior cuts only the ones on top of it\n    let foe = null;\n    for (const f of foes) {\n      const r = f.cls ? (me.cls === 'WARRIOR' ? 90 : 110) : (me.cls === 'WARRIOR' ? 36 : 0);\n      if (dist(f) < r && (!foe || dist(f) < dist(foe))) foe = f;\n    }\n    // at the bird, a warrior keeps rival players off its hunters\n    if (!foe && me.cls === 'WARRIOR' && bird && dist(bird) < 220) {\n      for (const f of obs.enemies) if (Math.hypot(f.x - bird.x, f.y - bird.y) < 220 && (!foe || dist(f) < dist(foe))) foe = f;\n    }\n    if (foe && !act.cmd) {\n      fight(this, me, foe, act);\n      act.think = { goal: 'FIGHT', why: 'IN THE WAY', plan: 'RAID', mood: 'RECKLESS', target: { kind: foe.cls ? 'player' : 'soldier', id: foe.id, x: foe.x, y: foe.y } };\n      return act;\n    }\n\n    if (!bird) {\n      // the birds are still in the air: head down the road toward where theirs lands\n      const far = obs.eagles.find((e) => e.team !== me.team);\n      const to = far && far.state !== 'gone' ? far : { x: me.x, y: me.y };\n      act.goTo = { x: to.x, y: to.y };\n      act.think = { goal: 'ROAM', why: 'BIRD STILL UP', plan: 'RAID' };\n      return act;\n    }\n\n    buyGear(this, me, act, 0); // gold is never saved: armour now\n    // back from a respawn: wait a few seconds at home for one partner, never longer\n    const own = obs.eagles.find((e) => e.team === me.team && e.state === 'down');\n    if (this.waitT > 0 && own) {\n      this.waitT -= 0.1;\n      const buddy = obs.allies.some((a) => !a.dead && !a.aboard && Math.hypot(a.x - me.x, a.y - me.y) < 140);\n      if (!buddy) {\n        const m = own.mouth || own;\n        act.goTo = { x: m.x, y: m.y };\n        act.think = { goal: 'RALLY', why: 'ONE PARTNER', plan: 'RAID', target: { kind: 'point', x: m.x, y: m.y } };\n        return act;\n      }\n      this.waitT = 0;\n    }\n    siege(this, me, bird, act);\n    if (me.hp < me.maxHp * 0.35 && me.food.berry > 0 && !foes.some((f) => dist(f) < 160)) act.eatBerry = true;\n    act.think = { goal: 'PUSH', why: dist(bird) > 200 ? 'RUN THE ROAD' : 'HIT THE BIRD', plan: 'RAID', mood: 'RECKLESS', target: { kind: 'bird', id: bird.team, x: bird.x, y: bird.y } };\n    return act;\n  },\n});\n\n// ---- shared moves (every bot file stands alone, so these are copied) --------\n\n// the first key in `order` with a level still to buy\nfunction pickKey(me, order) {\n  for (const k of order) if (me.abilities[k] && me.abilities[k].lv < 3) return k;\n  return -1;\n}\n\n// strike the rival bird: a hunter stands off past the wing gust (it reaches\n// 76 px) and taps shots; a warrior walks in and swings E\nfunction siege(bot, me, bird, act) {\n  const d = Math.hypot(bird.x - me.x, bird.y - me.y);\n  act.aim = [bird.x, bird.y];\n  if (me.cls === 'HUNTER') {\n    if (d > 115) act.goTo = { x: bird.x, y: bird.y, reach: 1 };\n    else if (d < 84) act.move = [(me.x - bird.x) / d, (me.y - bird.y) / d];\n    if (d < 135) { bot.drawT++; act.fire = bot.drawT % 2 === 1; } // further out, the woods eat the shots\n  } else {\n    act.goTo = { x: bird.x, y: bird.y, reach: 1 };\n    act.work = d < 56;\n  }\n}\n\n// one exchange with a rival body, by class, with the four keys\nfunction fight(bot, me, foe, act) {\n  const d = Math.max(1, Math.hypot(foe.x - me.x, foe.y - me.y));\n  const lead = me.cls === 'HUNTER' ? d / 320 : 0.1;\n  act.aim = [foe.x + (foe.vx || 0) * lead, foe.y + (foe.vy || 0) * lead];\n  const ab = me.abilities;\n  if (me.cls === 'WARRIOR') {\n    act.goTo = { x: foe.x, y: foe.y };\n    if (ab[1].ready && d > 48 && d < 110) act.ability = 1;                         // rush in\n    else if (ab[2].ready && d < 34) act.ability = 2;                               // stomp\n    else if (ab[3].ready && d < 30 && foe.hp < foe.maxHp * 0.45) act.ability = 3;  // execute\n    bot.swing = !bot.swing;\n    act.fire = d < 40 && bot.swing;\n  } else {\n    if (d < 100) act.move = [(me.x - foe.x) / d, (me.y - foe.y) / d];\n    else if (d > 220) act.goTo = { x: foe.x, y: foe.y };\n    if (ab[1].ready && d < 110) act.ability = 1;                                   // net, and the kick back\n    else if (ab[0].ready && d > 150 && d < 400) act.ability = 0;                   // piercing shot\n    bot.drawT++;\n    act.fire = bot.drawT < 8;\n    if (!act.fire) bot.drawT = 0;\n  }\n  if (me.hp < me.maxHp * 0.3 && d < 60) act.dodge = true;\n}\n\n// a resource node to work near `home`: the nearest of `kinds` within `range`,\n// skipping any the pathfinder found no way to (me.nav says 'fail' the think\n// after a goTo with no route)\nfunction pickNode(bot, obs, home, range, kinds) {\n  const me = obs.me;\n  bot.bad = bot.bad || {};\n  if (me.nav === 'fail' && bot.node) bot.bad[bot.node.key] = true;\n  let best = null, bd = Infinity;\n  for (const n of obs.nodes) {\n    const key = n.tx + ',' + n.ty;\n    if (!kinds.includes(n.kind) || bot.bad[key]) continue;\n    const x = n.tx * 16 + 8, y = n.ty * 16 + 8;\n    if (Math.hypot(x - home.x, y - home.y) > range) continue;\n    const d = Math.hypot(x - me.x, y - me.y) * (n.kind === 'tree' ? 1.5 : 1); // anything but a pine is worth a detour\n    if (d < bd) { bd = d; best = { x, y, kind: n.kind, key }; }\n  }\n  bot.node = best;\n  return best;\n}\n\n// work a node: walk up beside it and hold E (a rock needs no key: standing by it mines it)\nfunction work(me, n, act) {\n  const d = Math.hypot(n.x - me.x, n.y - me.y);\n  act.goTo = { x: n.x, y: n.y, reach: 1 };\n  act.aim = [n.x, n.y];\n  act.work = d < 28 && n.kind !== 'rock';\n}\n\n// gold to spare: the next gear piece, round the four in turn (the obs does\n// not say which pieces are already bought, so a full one is just skipped)\nfunction buyGear(bot, me, act, keep) {\n  if (act.cmd || me.gold < keep + 10) return;\n  bot.gear = ((bot.gear || 0) + 1) % 4;\n  act.cmd = { kind: 'gear', piece: bot.gear };\n}\n");
botLibAdd("shepherd", "// SHEPHERD: rides its own soldier waves. Every half minute the barracks\n// behind its bird send a column down the road; SHEPHERD waits at the head of\n// its spur for one, walks behind the front soldier, clears the rival column\n// and anyone who comes out to meet it. Once the column is over the middle\n// of the map it commits: soldiers beside it, it goes for the rival bird. Between waves it chops the woods by the spur. Wins the\n// middle of the map; slow to answer a raid that skips the road.\ndefineBot({\n  name: 'SHEPHERD',\n  author: 'Softfall',\n  version: '1.0',\n\n  init(hello) { this.drawT = 0; this.swing = false; },\n\n  think(obs) {\n    const me = obs.me;\n    if (me.dead || me.aboard || me.falling) return { think: { goal: 'IDLE', why: me.dead ? 'DOWN' : 'RIDING' } };\n    const act = {};\n    const dist = (o) => Math.hypot(o.x - me.x, o.y - me.y);\n    if (me.skillPts > 0) { const k = pickKey(me, me.cls === 'WARRIOR' ? [2, 1, 3, 0] : [0, 1, 3, 2]); if (k >= 0) act.cmd = { kind: 'ability', i: k }; }\n\n    const own = obs.eagles.find((e) => e.team === me.team && e.state === 'down');\n    const bird = obs.eagles.find((e) => e.team !== me.team && e.state === 'down');\n    if (!own || !bird) { act.goTo = { x: me.x, y: me.y }; act.think = { goal: 'IDLE', why: 'NO ROOST YET' }; return act; }\n    const toBird = (o) => Math.hypot(o.x - bird.x, o.y - bird.y);\n\n    // the front of our column: the soldier of ours nearest the rival bird\n    const ours = obs.soldiers.filter((s) => s.team === me.team);\n    let front = null;\n    for (const s of ours) if (!front || toBird(s) < toBird(front)) front = s;\n    const foes = obs.enemies.concat(obs.soldiers.filter((s) => s.team !== me.team));\n\n    // over the middle with soldiers of ours beside it: commit to the bird\n    const withMe = ours.filter((s) => dist(s) < 220).length;\n    const commit = withMe > 0 && toBird(me) < 1100;\n    // players first (they kill the column), then the rival column, near us or the\n    // front; committed, only what is on top of it\n    let foe = null, fd = Infinity;\n    for (const f of foes) {\n      const d = Math.min(dist(f), front ? Math.hypot(f.x - front.x, f.y - front.y) + 60 : Infinity) + (f.cls ? 0 : 50);\n      if (d < (commit ? (f.cls ? 140 : 90) : 200) && d < fd) { fd = d; foe = f; }\n    }\n    // a blow on our own bird with no column out: go home and answer it\n    if (own.hitT < 3 && (!front || toBird(front) > toBird(me) + 200) && dist(own) < 1200) {\n      for (const f of foes) if (Math.hypot(f.x - own.x, f.y - own.y) < 300 && (!foe || dist(f) < dist(foe))) foe = f;\n      if (!foe) {\n        act.goTo = { x: own.x, y: own.y, reach: 1 };\n        act.think = { goal: 'DEFEND', why: 'BIRD HIT', plan: 'WAVE' };\n        return act;\n      }\n    }\n    if (foe) {\n      fight(this, me, foe, act);\n      act.think = { goal: 'FIGHT', why: foe.cls ? 'AT THE COLUMN' : 'RIVAL COLUMN', plan: 'WAVE', target: { kind: foe.cls ? 'player' : 'soldier', id: foe.id, x: foe.x, y: foe.y } };\n      return act;\n    }\n    if (me.hp < me.maxHp * 0.6 && me.food.berry > 0) { act.eatBerry = true; act.think = { goal: 'EAT', why: 'LOW HP' }; return act; }\n    buyGear(this, me, act, 0);\n\n    // the column is at their bird, or three of ours stand by us near it: siege\n    if (commit && (toBird(front) < 400 || toBird(me) < 400)) {\n      siege(this, me, bird, act);\n      act.think = { goal: 'PUSH', why: 'COLUMN AT THE BIRD', plan: 'WAVE', mood: 'STEADY', target: { kind: 'bird', id: bird.team, x: bird.x, y: bird.y } };\n      return act;\n    }\n    // walk a step behind the front of a column that has left home\n    const mouth = own.mouth || own;\n    if (front && toBird(front) < toBird(mouth) - 64) {\n      const L = Math.max(1, toBird(front)), back = 36;\n      const x = front.x + (front.x - bird.x) / L * back, y = front.y + (front.y - bird.y) / L * back;\n      act.goTo = { x, y };\n      act.aim = [bird.x, bird.y];\n      act.think = { goal: 'ESCORT', why: ours.length + ' IN THE COLUMN', plan: 'WAVE', target: { kind: 'soldier', id: front.id, x: front.x, y: front.y } };\n      return act;\n    }\n    // between waves: chop by the head of the spur, where the next one passes\n    const n = pickNode(this, obs, mouth, 200, ['tree', 'bush', 'rock']);\n    if (n) { work(me, n, act); act.think = { goal: 'GATHER', why: 'WAITING ON A WAVE', plan: 'WAVE', target: { kind: 'point', x: n.x, y: n.y } }; return act; }\n    act.goTo = { x: mouth.x, y: mouth.y };\n    act.think = { goal: 'RALLY', why: 'WAITING ON A WAVE', plan: 'WAVE', target: { kind: 'point', x: mouth.x, y: mouth.y } };\n    return act;\n  },\n});\n\n// ---- shared moves (every bot file stands alone, so these are copied) --------\n\n// the first key in `order` with a level still to buy\nfunction pickKey(me, order) {\n  for (const k of order) if (me.abilities[k] && me.abilities[k].lv < 3) return k;\n  return -1;\n}\n\n// strike the rival bird: a hunter stands off past the wing gust (it reaches\n// 76 px) and taps shots; a warrior walks in and swings E\nfunction siege(bot, me, bird, act) {\n  const d = Math.hypot(bird.x - me.x, bird.y - me.y);\n  act.aim = [bird.x, bird.y];\n  if (me.cls === 'HUNTER') {\n    if (d > 115) act.goTo = { x: bird.x, y: bird.y, reach: 1 };\n    else if (d < 84) act.move = [(me.x - bird.x) / d, (me.y - bird.y) / d];\n    if (d < 135) { bot.drawT++; act.fire = bot.drawT % 2 === 1; } // further out, the woods eat the shots\n  } else {\n    act.goTo = { x: bird.x, y: bird.y, reach: 1 };\n    act.work = d < 56;\n  }\n}\n\n// one exchange with a rival body, by class, with the four keys\nfunction fight(bot, me, foe, act) {\n  const d = Math.max(1, Math.hypot(foe.x - me.x, foe.y - me.y));\n  const lead = me.cls === 'HUNTER' ? d / 320 : 0.1;\n  act.aim = [foe.x + (foe.vx || 0) * lead, foe.y + (foe.vy || 0) * lead];\n  const ab = me.abilities;\n  if (me.cls === 'WARRIOR') {\n    act.goTo = { x: foe.x, y: foe.y };\n    if (ab[1].ready && d > 48 && d < 110) act.ability = 1;                         // rush in\n    else if (ab[2].ready && d < 34) act.ability = 2;                               // stomp\n    else if (ab[3].ready && d < 30 && foe.hp < foe.maxHp * 0.45) act.ability = 3;  // execute\n    bot.swing = !bot.swing;\n    act.fire = d < 40 && bot.swing;\n  } else {\n    if (d < 100) act.move = [(me.x - foe.x) / d, (me.y - foe.y) / d];\n    else if (d > 220) act.goTo = { x: foe.x, y: foe.y };\n    if (ab[1].ready && d < 110) act.ability = 1;                                   // net, and the kick back\n    else if (ab[0].ready && d > 150 && d < 400) act.ability = 0;                   // piercing shot\n    bot.drawT++;\n    act.fire = bot.drawT < 8;\n    if (!act.fire) bot.drawT = 0;\n  }\n  if (me.hp < me.maxHp * 0.3 && d < 60) act.dodge = true;\n}\n\n// a resource node to work near `home`: the nearest of `kinds` within `range`,\n// skipping any the pathfinder found no way to (me.nav says 'fail' the think\n// after a goTo with no route)\nfunction pickNode(bot, obs, home, range, kinds) {\n  const me = obs.me;\n  bot.bad = bot.bad || {};\n  if (me.nav === 'fail' && bot.node) bot.bad[bot.node.key] = true;\n  let best = null, bd = Infinity;\n  for (const n of obs.nodes) {\n    const key = n.tx + ',' + n.ty;\n    if (!kinds.includes(n.kind) || bot.bad[key]) continue;\n    const x = n.tx * 16 + 8, y = n.ty * 16 + 8;\n    if (Math.hypot(x - home.x, y - home.y) > range) continue;\n    const d = Math.hypot(x - me.x, y - me.y) * (n.kind === 'tree' ? 1.5 : 1); // anything but a pine is worth a detour\n    if (d < bd) { bd = d; best = { x, y, kind: n.kind, key }; }\n  }\n  bot.node = best;\n  return best;\n}\n\n// work a node: walk up beside it and hold E (a rock needs no key: standing by it mines it)\nfunction work(me, n, act) {\n  const d = Math.hypot(n.x - me.x, n.y - me.y);\n  act.goTo = { x: n.x, y: n.y, reach: 1 };\n  act.aim = [n.x, n.y];\n  act.work = d < 28 && n.kind !== 'rock';\n}\n\n// gold to spare: the next gear piece, round the four in turn (the obs does\n// not say which pieces are already bought, so a full one is just skipped)\nfunction buyGear(bot, me, act, keep) {\n  if (act.cmd || me.gold < keep + 10) return;\n  bot.gear = ((bot.gear || 0) + 1) % 4;\n  act.cmd = { kind: 'gear', piece: bot.gear };\n}\n");
botLibAdd("starter", "// STARTER: the template bot. Copy this file to begin your own.\n// Rules of the road (docs/bots/api.md has the whole contract):\n//   - think(obs) is called 10 times a second for YOUR seat only, with what your\n//     player could see. Return an act: the keys you are holding, plus a thought.\n//   - Held keys (move, goTo, aim, fire, work, slide) stay held until your next act.\n//     One-shot keys (dodge, ability, eatBerry, cmd...) fire once.\n//   - `this` is your bot object, so keep memory on it (this.drawT below).\ndefineBot({\n  name: 'STARTER',\n  author: 'Softfall',\n  version: '1.0',\n\n  init(hello) {\n    this.team = hello.team;\n    this.mid = hello.map.world * hello.map.tile / 2; // the map's centre, px\n    this.drawT = 0; // thinks spent drawing the current shot\n  },\n\n  think(obs) {\n    const me = obs.me;\n    if (me.dead || me.aboard) return { think: { goal: 'IDLE', why: me.dead ? 'DOWN' : 'RIDING' } };\n    const act = {};\n\n    // a free skill point: spend it on the lowest key (ability on a key with a\n    // point waiting buys a level instead of casting)\n    if (me.skillPts > 0) {\n      let best = 0;\n      for (const a of me.abilities) if (a.lv < me.abilities[best].lv) best = a.key;\n      act.ability = best;\n    }\n\n    // the nearest thing to fight: a rival player, else a rival soldier\n    const foes = obs.enemies.concat(obs.soldiers.filter((s) => s.team !== me.team));\n    let foe = null, fd = Infinity;\n    for (const f of foes) {\n      const d = Math.hypot(f.x - me.x, f.y - me.y);\n      if (d < fd) { fd = d; foe = f; }\n    }\n\n    // hurt, nobody close, a berry in the pouch: eat (a hit knocks the meal away)\n    if (me.hp < me.maxHp * 0.5 && me.food.berry > 0 && fd > 120) {\n      act.eatBerry = true;\n      act.think = { goal: 'EAT', why: 'LOW HP' };\n      return act;\n    }\n\n    const melee = me.cls === 'WARRIOR';\n    if (foe && fd < (melee ? 160 : 220)) {\n      // lead a moving target a little: where it will be in a fifth of a second\n      const tx = foe.x + (foe.vx || 0) * 0.2, ty = foe.y + (foe.vy || 0) * 0.2;\n      act.aim = [tx, ty];\n      const kind = obs.enemies.includes(foe) ? 'player' : 'soldier';\n      act.think = { goal: 'FIGHT', why: melee ? 'IN REACH' : 'IN RANGE', target: { kind, id: foe.id, x: foe.x, y: foe.y } };\n      if (melee) {\n        act.goTo = { x: foe.x, y: foe.y };\n        act.fire = fd < 40 && !this.fire; // tap the swing\n      } else {\n        // a bow: hold the draw 7 thinks (0.7 s), let go for one, and keep your distance\n        if (fd < 110) act.move = [(me.x - foe.x) / fd, (me.y - foe.y) / fd];\n        this.drawT++;\n        act.fire = this.drawT < 8;\n        if (!act.fire) this.drawT = 0;\n      }\n      this.fire = act.fire;\n      return act;\n    }\n    this.drawT = 0;\n\n    // nothing to fight: go for the rival bird once it has landed\n    const bird = obs.eagles.find((e) => e.team !== me.team && e.state === 'down');\n    if (bird) {\n      const d = Math.hypot(bird.x - me.x, bird.y - me.y);\n      act.aim = [bird.x, bird.y];\n      act.think = { goal: 'PUSH', why: 'BIRD IS DOWN', target: { kind: 'bird', id: bird.team, x: bird.x, y: bird.y } };\n      if (melee || d > 100) act.goTo = { x: bird.x, y: bird.y, reach: 1 };\n      if (melee) act.work = d < 40; // E on the bird: a swing chips its nerve\n      else if (d < 140) { this.drawT++; act.fire = this.drawT % 8 !== 0; }\n      return act;\n    }\n\n    // still in the air, or no bird yet: head for the middle of the map\n    act.goTo = { x: this.mid, y: this.mid };\n    act.think = { goal: 'ROAM', why: 'NO BIRD YET' };\n    return act;\n  },\n});\n");
